class Solution:
    def smallestNumber(self, n: int, t: int) -> int:
        # Start checking from n upwards
        curr = n
        while True:
            # Calculate the product of digits
            product = 1
            temp = curr
            while temp > 0:
                digit = temp % 10
                if digit == 0:
                    product = 0
                    break
                product *= digit
                temp //= 10

            # Check if the product is divisible by t
            if (product % t == 0):
                return curr
            curr += 1

