class Solution:
    def buttonWithLongestTime(self, events: List[List[int]]) -> int:
        if not events:
            return -1

        # Initialize with the first event
        max_time = events[0][1]
        best_index = events[0][0]
        prev_time = events[0][1]

        # Iterate through the rest of the events
        for i in range(1, len(events)):
            curr_idx, curr_time = events[i]
            time_taken = curr_time - prev_time

            # Update if we found a longer time
            if time_taken > max_time:
                max_time = time_taken
                best_index = curr_idx
            # If times are equal, choose the button with the smaller index
            elif time_taken == max_time:
                if curr_idx < best_index:
                    best_index = curr_idx

            prev_time = curr_time

        return best_index

