        # Floyd-Warshall for day1: compute max multiplier from initialCurrency to all nodes
        dist1 = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    dist1[i][j] = adj1[i][j]
                else:
                    dist1[i][j] = 1.0

        for k in range(n):
            for i in range(n):
                for j in range(n):
                    dist1[i][j] = max(dist1[i][j], dist1[i][k] * dist1[k][j])

        # Floyd-Warshall for day2: compute max multiplier between all pairs
        dist2 = [[0.0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    dist2[i][j] = adj2[i][j]
                else:
