        for k in range(n):
            for i in range(n):
                for j in range(n):
                    dist2[i][j] = max(dist2[i][j], dist2[i][k] * dist2[k][j])

        # Now, for each node u that is reachable from initialCurrency in day1, 
        # compute the max multiplier from u to initialCurrency in day2.
        ans = 0.0
        init_idx = currency_to_idx[initialCurrency]

        for j in range(n):
            # Check if j is reachable from initialCurrency in day1
            if dist1[init_idx][j] > 0:
                # Then compute multiplier from j to initialCurrency in day2
                val = dist2[j][init_idx]
                if val > 0:
                    ans = max(ans, dist1[init_idx][j] * val)

        # If no conversions give more than 1.0, then the answer is at least 1.0
        if ans < 1.0:
