class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        # Helper function to build the graph including inverse edges
        def build_graph(pairs, rates):
            g = defaultdict(dict)
            for (start, target), rate in zip(pairs, rates):
                g[start][target] = rate
                # Add inverse edge: target -> start with rate 1/rate
                g[target][start] = 1.0 / rate
            return g

        # Build graphs for Day 1 and Day 2
        g1 = build_graph(pairs1, rates1)
        g2 = build_graph(pairs2, rates2)

        # Build reversed graph for Day 2: 
        # If we have an edge u->v in g2, then in g2_rev we have v->u with the same rate.
        # This allows us to compute the max multiplier from a node back to initialCurrency in g2
        g2_rev = defaultdict(dict)
        for u, edges in g2.items():
            for v, rate in edges.items():
                g2_rev[v][u] = rate

        # DFS to compute max multiplier from start_node to all reachable nodes
        def get_max_multipliers(start_node, graph):
            memo = {}
            stack = [(start_node, 1.0)]
            while stack:
                u, current_mult = stack.pop()
                if u in memo:
                    continue
                memo[u] = current_mult
                for v, rate in graph[u].items():
                    new_val = current_mult * rate
                    if v not in memo or new_val > memo[v]:
                        memo[v] = new_val
                        stack.append((v, new_val))
            return memo

        # Compute max multipliers from initialCurrency in g1 (forward path)
        dp1 = get_max_multipliers(initialCurrency, g1)

        # Compute max multipliers from initialCurrency in g2_rev (which corresponds to paths from nodes to initialCurrency in g2)
        dp2 = get_max_multipliers(initialCurrency, g2_rev)

        # Calculate the maximum amount by multiplying the path from initialCurrency to u in g1 and from u to initialCurrency in g2
        ans = 0.0
        for u in dp1:
            if u in dp2:
                val = dp1[u] * dp2[u]
                if val > ans:
                    ans = val

        return ans

