class Solution:
    def checkValidCuts(self, n: int, rectangles: List[List[int]]) -> bool:
        def can_split_horizontal():
            # Sort rectangles by their start_y
            rects = sorted(rectangles, key=lambda r: r[1])
            m = len(rects)
            if m < 3:
                return False

            # Precompute prefix max of end_y
            # P[i] stores the max end_y of rectangles[0...i]
            P = [0] * m
            curr_max = -float('inf')
            for i in range(m):
                if rects[i][3] > curr_max:
                    curr_max = rects[i][3]
                P[i] = curr_max

            # Precompute suffix min of start_y
            # S[i] stores the min start_y of rectangles[i...m-1]
            S = [0] * m
            curr_min = float('inf')
            for i in range(m - 1, -1, -1):
                if rects[i][1] < curr_min:
                    curr_min = rects[i][1]
                S[i] = curr_min

            # valid_prefix[i] is True if there exists k <= i such that P[k] <= S[k+1]
            # This represents that a valid first cut exists after index k (where k <= i)
            valid_prefix = [False] * m
            for i in range(m):
                # Check if current rectangle k=i can serve as the end of the first group
                if i + 1 < m and P[i] <= S[i+1]:
                    valid_prefix[i] = True
                else:
                    # Inherit from previous position
                    if i > 0:
                        valid_prefix[i] = valid_prefix[i-1]

            # Now try to find a second cut j > i
            # We iterate j from 1 to m-2
            # For a specific j, we need:
            # 1. P[j] <= S[j+2] (Second cut valid, separating group 2 and 3)
            # 2. There exists an i < j such that P[i] <= S[i+1] (First cut valid)
            #    This is covered by valid_prefix[j-1]

            for j in range(1, m - 1):
                if P[j] <= S[j+2] and valid_prefix[j-1]:
                    return True
            return False

        def can_split_vertical():
            # Sort rectangles by their start_x
            rects = sorted(rectangles, key=lambda r: r[0])
            m = len(rects)
            if m < 3:
                return False

            # Precompute prefix max of end_x
            P = [0] * m
            curr_max = -float('inf')
            for i in range(m):
                if rects[i][2] > curr_max:
                    curr_max = rects[i][2]
                P[i] = curr_max

            # Precompute suffix min of start_x
            S = [0] * m
            curr_min = float('inf')
            for i in range(m - 1, -1, -1):
                if rects[i][0] < curr_min:
                    curr_min = rects[i][0]
                S[i] = curr_min

            valid_prefix = [False] * m
            for i in range(m):
                if i + 1 < m and P[i] <= S[i+1]:
                    valid_prefix[i] = True
                else:
                    if i > 0:
                        valid_prefix[i] = valid_prefix[i-1]

            for j in range(1, m - 1):
                if P[j] <= S[j+2] and valid_prefix[j-1]:
                    return True
            return False

        return can_split_horizontal() or can_split_vertical()
